(()=>{
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const scene=document.querySelector('.noise-scene'),sticky=document.querySelector('.noise-sticky'),cloud=[...document.querySelectorAll('.noise-cloud>span')],hero=document.querySelector('.hero-sculpture'),bar=document.querySelector('.reading-progress');
 const targets=document.querySelectorAll('.section-top,.section h2,.section .intro,.option,.extra,.controls,.projection,.storm-card,.journey');
 targets.forEach((el,i)=>{el.classList.add('reveal');if(el.classList.contains('option'))el.style.setProperty('--reveal-delay',`${Array.from(el.parentElement.children).indexOf(el)*140}ms`)});
 const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target)}}),{threshold:.12});
 targets.forEach(el=>observer.observe(el));document.documentElement.classList.add('motion-ready');
 const clamp=(x,a=0,b=1)=>Math.min(b,Math.max(a,x));let queued=false;
 function render(){queued=false;const scroll=window.scrollY,total=document.documentElement.scrollHeight-innerHeight;bar.style.transform=`scaleX(${total>0?scroll/total:0})`;if(reduced.matches)return;hero.style.setProperty('--hero-shift',`${scroll*.12}px`);hero.style.setProperty('--hero-turn',`${scroll*.015}deg`);const rect=scene.getBoundingClientRect(),p=clamp((82-rect.top)/(scene.offsetHeight-sticky.offsetHeight)),compact=innerWidth<800?.52:1;sticky.style.setProperty('--scene-progress',p);sticky.style.setProperty('--clarity',clamp((p-.25)/.45));sticky.style.setProperty('--goal-scale',.7+.3*clamp(p/.8));cloud.forEach(el=>{let css=getComputedStyle(el),x=+css.getPropertyValue('--x')*compact,y=+css.getPropertyValue('--y'),r=+css.getPropertyValue('--r');el.style.transform=`translate(${x*(1-p*.8)}px,${y*(1-p*.8)}px) rotate(${r*(1-p)}deg) scale(${1-p*.6})`;el.style.opacity=1-clamp(p/.65)});}
 function request(){if(!queued){queued=true;requestAnimationFrame(render)}}addEventListener('scroll',request,{passive:true});addEventListener('resize',request);reduced.addEventListener('change',()=>location.reload());render();
 const card=document.querySelector('.projection');if(matchMedia('(pointer:fine)').matches&&!reduced.matches){card.addEventListener('pointermove',e=>{const r=card.getBoundingClientRect();card.style.setProperty('--tilt-x',`${(e.clientX-r.left-r.width/2)/r.width*5}deg`);card.style.setProperty('--tilt-y',`${-(e.clientY-r.top-r.height/2)/r.height*5}deg`)});card.addEventListener('pointerleave',()=>{card.style.setProperty('--tilt-x','0deg');card.style.setProperty('--tilt-y','0deg')})}
})();
